class TestUART(unittest.TestCase):
    def test_tx_callback(self):
        uart = UART()
        out = []
        uart.on_tx = lambda b: out.append(b)
        uart.write8(0x00, 0x41)  # TX 'A'
        uart.write8(0x00, 0x42)  # TX 'B'
        self.assertEqual(out, [0x41, 0x42])

    def test_rx_inject(self):
        uart = UART()
        uart.inject_input(b"Hi")
        # STATUS should show RX available
        status = uart.read8(0x02)
        self.assertTrue(status & 0x02)
        # Read two bytes
        self.assertEqual(uart.read8(0x01), ord("H"))
        self.assertEqual(uart.read8(0x01), ord("i"))
        # Now empty
        status = uart.read8(0x02)
        self.assertFalse(status & 0x02)

    def test_tx_drain(self):
        uart = UART()
        uart.write8(0x00, 0x41)
        uart.write8(0x00, 0x42)
        self.assertEqual(uart.drain_tx(), "AB")  # drain_tx returns str
        self.assertEqual(uart.drain_tx(), "")

    def test_tx_ring_batch_callback(self):
        """TX ring buffer drain fires on_tx_batch with correct data."""
        uart = UART()
        # Simulate CPU memory: descriptor at address 0x1000
        #   +0: head (LE u64)  +8: ring data
        mem = bytearray(0x2000)
        uart._cpu_mem = mem
        # Register ring base via MMIO writes (LE bytes of 0x1000)
        ring_base = 0x1000
        for i in range(8):
            uart.write8(0x08 + i, (ring_base >> (i * 8)) & 0xFF)
        self.assertEqual(uart._tx_ring_base, ring_base)
        # Write 5 bytes into ring buffer area
        payload = b"Hello"
        head = len(payload)
        mem[ring_base:ring_base + 8] = head.to_bytes(8, 'little')
        mem[ring_base + 8:ring_base + 8 + head] = payload
        # Set batch callback
        batches = []
        uart.on_tx_batch = lambda data: batches.append(data)
        # Trigger flush
        uart.write8(0x06, 0x01)
        self.assertEqual(batches, [b"Hello"])
        # Head should be reset to 0
        self.assertEqual(int.from_bytes(mem[ring_base:ring_base + 8], 'little'), 0)
        # tx_buffer should also have accumulated the bytes
        self.assertEqual(uart.drain_tx(), "Hello")

    def test_tx_ring_fallback_per_byte(self):
        """Without on_tx_batch, drain falls back to per-byte on_tx."""
        uart = UART()
        mem = bytearray(0x2000)
        uart._cpu_mem = mem
        ring_base = 0x1000
        for i in range(8):
            uart.write8(0x08 + i, (ring_base >> (i * 8)) & 0xFF)
        payload = b"AB"
        mem[ring_base:ring_base + 8] = len(payload).to_bytes(8, 'little')
        mem[ring_base + 8:ring_base + 8 + len(payload)] = payload
        per_byte = []
        uart.on_tx = lambda b: per_byte.append(b)
        uart.write8(0x06, 0x01)
        self.assertEqual(per_byte, [0x41, 0x42])

    def test_tx_ring_no_drain_without_base(self):
        """Flush is a no-op if ring base was never registered."""
        uart = UART()
        uart._cpu_mem = bytearray(256)
        batches = []
        uart.on_tx_batch = lambda data: batches.append(data)
        uart.write8(0x06, 0x01)
        self.assertEqual(batches, [])

    def test_tx_ring_no_drain_zero_head(self):
        """Flush with head=0 does not fire callbacks."""
        uart = UART()
        mem = bytearray(0x2000)
        uart._cpu_mem = mem
        ring_base = 0x1000
        for i in range(8):
            uart.write8(0x08 + i, (ring_base >> (i * 8)) & 0xFF)
        # head = 0 (already zeroed)
        batches = []
        uart.on_tx_batch = lambda data: batches.append(data)
        uart.write8(0x06, 0x01)
        self.assertEqual(batches, [])


class TestTimer(unittest.TestCase):
    def test_tick_count(self):
        timer = Timer()
        # Enable timer: CONTROL is at offset 0x08
        timer.write8(0x08, 0x01)  # CTRL bit 0 = enable
        for _ in range(100):
            timer.tick(1)
        # Read counter (32-bit, little-endian at offset 0)
        lo = timer.read8(0x00)
        hi = timer.read8(0x01)
        count = lo | (hi << 8)
        self.assertEqual(count, 100)


class TestStorage(unittest.TestCase):
    def test_create_and_rw(self):
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            stor = Storage()
            # Remove the temp so load_image creates a fresh image
            os.unlink(path)
            stor.load_image(path)  # creates default 1 MiB image
            self.assertGreater(stor.total_sectors, 0)
            self.assertTrue(stor.status & 0x80)
            raw_total = bytes(stor.read8(offset)
                              for offset in range(0x11, 0x15))
            self.assertEqual(struct.unpack("<I", raw_total)[0], 2048)

            # Write test data into internal buffer
            test_data = bytes(range(256))
            stor._image_data[:256] = test_data
            self.assertEqual(stor._image_data[:10], bytes(range(10)))

            # Save and reload
            stor.save_image()
            stor2 = Storage()
            stor2.load_image(path)
            self.assertEqual(stor2._image_data[:10], bytes(range(10)))
        finally:
            if os.path.exists(path):
                os.unlink(path)

    def test_no_image(self):
        stor = Storage()
        self.assertFalse(stor.status & 0x80)
        self.assertEqual([stor.read8(offset) for offset in range(0x11, 0x15)],
                         [0, 0, 0, 0])

    def test_total_sector_register_is_exact_u32_le(self):
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            f.truncate(8192 * SECTOR_SIZE)
        try:
            stor = Storage(path)
            raw = bytes(stor.read8(offset) for offset in range(0x11, 0x15))
            self.assertEqual(struct.unpack("<I", raw)[0], 8192)
            stor.write8(0x11, 0)
            raw = bytes(stor.read8(offset) for offset in range(0x11, 0x15))
            self.assertEqual(struct.unpack("<I", raw)[0], 8192)
        finally:
            os.unlink(path)

    def test_fixed_capacity_transfer_boundaries(self):
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            f.truncate(2 * SECTOR_SIZE)
        try:
            stor = Storage(path)
            capacity = stor.total_sectors
            image_size = len(stor._image_data)

            payload = bytes([0xA5]) * SECTOR_SIZE
            stor.write_sectors(capacity - 1, 1, payload)
            self.assertEqual(stor.read_sectors(capacity - 1, 1), payload)

            with self.assertRaises(ValueError):
                stor.read_sectors(capacity, 1)
            self.assertTrue(stor.error)
            self.assertEqual(stor.total_sectors, capacity)
            self.assertEqual(len(stor._image_data), image_size)

            with self.assertRaises(ValueError):
                stor.write_sectors(capacity - 1, 2, payload * 2)
            self.assertTrue(stor.error)
            self.assertEqual(stor.total_sectors, capacity)
            self.assertEqual(len(stor._image_data), image_size)
        finally:
            os.unlink(path)

    def test_oob_mmio_commands_set_error_without_mutating_capacity(self):
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            f.truncate(2 * SECTOR_SIZE)
        try:
            stor = Storage(path)
            original = bytes(stor._image_data)
            stor.sector_num = stor.total_sectors
            stor.sec_count = 1

            stor.write8(0x00, 0x01)
            self.assertTrue(stor.read8(0x01) & 0x02)
            stor.data_port_buf = bytearray(SECTOR_SIZE)
            stor.write8(0x00, 0x02)
            self.assertTrue(stor.read8(0x01) & 0x02)

            self.assertEqual(stor.total_sectors, 2)
            self.assertEqual(bytes(stor._image_data), original)
            raw = bytes(stor.read8(offset) for offset in range(0x11, 0x15))
            self.assertEqual(struct.unpack("<I", raw)[0], 2)
        finally:
            os.unlink(path)

    def test_short_write_is_rejected_without_shrinking_image(self):
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            f.truncate(2 * SECTOR_SIZE)
        try:
            stor = Storage(path)
            with self.assertRaises(ValueError):
                stor.write_sectors(0, 1, b"short")
            self.assertTrue(stor.error)
            self.assertEqual(stor.total_sectors, 2)
            self.assertEqual(len(stor._image_data), 2 * SECTOR_SIZE)
        finally:
            os.unlink(path)

    def test_swap_image(self):
        """swap_image() saves the old image and loads the new one."""
        import tempfile, struct
        from diskutil import MP64FS
        # Create two temp images
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f1:
            path1 = f1.name
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f2:
            path2 = f2.name
        try:
            os.unlink(path1)
            os.unlink(path2)
            # Format image A with a marker
            fs1 = MP64FS(total_sectors=64)
            fs1.format()
            fs1.inject_file("hello.txt", b"image-A-data", ftype=2)
            fs1.save(path1)
            # Format image B with a different marker
            fs2 = MP64FS(total_sectors=64)
            fs2.format()
            fs2.inject_file("world.txt", b"image-B-data", ftype=2)
            fs2.save(path2)

            stor = Storage(path1)
            self.assertTrue(stor.status & 0x80)
            # Confirm image A is loaded
            live_fs = MP64FS(bytearray(stor._image_data))
            names = {e.name for e in live_fs.list_files()}
            self.assertIn("hello.txt", names)

            # Swap to image B
            stor.swap_image(path2)
            self.assertTrue(stor.status & 0x80)
            self.assertEqual(stor.image_path, path2)
            live_fs = MP64FS(bytearray(stor._image_data))
            names = {e.name for e in live_fs.list_files()}
            self.assertIn("world.txt", names)
            self.assertNotIn("hello.txt", names)

            # swap resets device state
            self.assertEqual(stor.sector_num, 0)
            self.assertEqual(stor.dma_addr, 0)
            self.assertFalse(stor.error)
        finally:
            for p in (path1, path2):
                if os.path.exists(p):
                    os.unlink(p)

    def test_detach_image(self):
        """detach_image() clears the image and saves it first."""
        import tempfile
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            stor = Storage()
            stor.load_image(path)
            self.assertTrue(stor.status & 0x80)
            stor.detach_image(save=True)
            self.assertFalse(stor.status & 0x80)
            self.assertIsNone(stor.image_path)
            self.assertEqual(len(stor._image_data), 0)
            # File should exist on disk (was saved)
            self.assertTrue(os.path.exists(path))
        finally:
            if os.path.exists(path):
                os.unlink(path)

    def test_extract_file_from_image(self):
        """Files can be read from a live Storage image via MP64FS."""
        import tempfile
        from diskutil import MP64FS
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            fs = MP64FS(total_sectors=64)
            fs.format()
            payload = b"Hello from inside the image!\\n"
            fs.inject_file("greeting.txt", payload, ftype=2)
            fs.save(path)

            stor = Storage(path)
            live_fs = MP64FS(bytearray(stor._image_data))
            data = live_fs.read_file("greeting.txt")
            self.assertEqual(data.rstrip(b"\\x00"), payload)
        finally:
            if os.path.exists(path):
                os.unlink(path)


class TestDeviceBus(unittest.TestCase):
    def test_route_uart(self):
        bus = DeviceBus()
        uart = UART()
        bus.register(uart)
        out = []
        uart.on_tx = lambda b: out.append(b)
        # UART_BASE (0x0000) is already the MMIO aperture offset
        bus.write8(UART_BASE, 0x48)  # TX 'H'
        self.assertEqual(out, [0x48])

    def test_route_sysinfo(self):
        bus = DeviceBus()
        si = SystemInfo(bank0_size=256 * 1024)
        bus.register(si)
        # SysInfo register 0x00: 64'h4D50_3634_0002_0001 (LE bytes)
        # bytes 0-3: version part, bytes 4-7: board ID "MP64" reversed
        self.assertEqual(bus.read8(SYSINFO_BASE + 0), 0x01)  # ver minor
        self.assertEqual(bus.read8(SYSINFO_BASE + 4), ord("4"))
        self.assertEqual(bus.read8(SYSINFO_BASE + 5), ord("6"))
        self.assertEqual(bus.read8(SYSINFO_BASE + 6), ord("P"))
        self.assertEqual(bus.read8(SYSINFO_BASE + 7), ord("M"))


class TestNIC(unittest.TestCase):
    """Tests for the NetworkDevice (NIC) peripheral."""

    def test_present_and_link_up(self):
        nic = NetworkDevice()
        status = nic.read8(0x01)
        self.assertTrue(status & 0x80)   # present
        self.assertTrue(status & 0x04)   # link up
        self.assertFalse(status & 0x02)  # no RX pending

    def test_status_reports_transient_tx_busy(self):
        """Compatibility STATUS owns TX until a later device tick."""
        nic = NetworkDevice()
        nic._mem_read = lambda _addr: 0xA5
        nic.frame_len = 1
        nic._execute_cmd(0x01)
        self.assertTrue(nic.read8(0x01) & 0x01)
        self.assertEqual(nic.tx_count, 0)
        self.assertEqual(nic.read8(0x0D) & 0x02, 0)
        nic.tick(1)
        self.assertFalse(nic.read8(0x01) & 0x01)
        self.assertEqual(nic.tx_count, 1)
        self.assertEqual(nic.read8(0x0D) & 0x02, 0x02)

    def test_mac_address(self):
        mac = b'\x02\x4D\x50\x36\x34\x00'
        nic = NetworkDevice(mac=mac)
        for i, b in enumerate(mac):
            self.assertEqual(nic.read8(0x0E + i), b)

    def test_inject_and_recv_frame(self):
        nic = NetworkDevice()
        frame = b'Hello NIC!'
        ram = bytearray(64)
        nic._mem_write = lambda addr, val: ram.__setitem__(addr, val & 0xFF)
        nic.inject_frame(frame)
        # STATUS should show RX available
        self.assertTrue(nic.read8(0x01) & 0x02)
        self.assertEqual(nic.rx_count, 1)
        # Receive through the same DMA contract used by BIOS and RTL.
        nic._execute_cmd(0x02)  # RECV
        self.assertEqual(nic.frame_len, len(frame))
        self.assertEqual(bytes(ram[:len(frame)]), frame)
        # RX queue empty now
        self.assertFalse(nic.read8(0x01) & 0x02)

    def test_data_window_is_address_indexed_not_a_fifo(self):
        nic = NetworkDevice()
        nic.write8(0x20, 0xDE)
        nic.write8(0x21, 0xAD)
        nic.write8(0x7F, 0x5E)

        self.assertEqual(nic.read8(0x20), 0xDE)
        self.assertEqual(nic.read8(0x20), 0xDE)
        self.assertEqual(nic.read8(0x21), 0xAD)
        self.assertEqual(nic.read8(0x7F), 0x5E)
        self.assertEqual(nic.read8(0x22), 0)

        nic._execute_cmd(0x04)
        self.assertEqual(nic.read8(0x20), 0)
        self.assertEqual(nic.read8(0x21), 0)
        self.assertEqual(nic.read8(0x7F), 0)

    def test_tx_via_dma(self):
        """TX using DMA with mem_read callback."""
        nic = NetworkDevice()
        sent = []
        nic.on_tx_frame = lambda f: sent.append(f)
        # Simulate RAM with a simple dict
        ram = bytearray(256)
        msg = b'DMA frame!'
        ram[:len(msg)] = msg
        nic._mem_read = lambda addr: ram[addr % len(ram)]
        # Set DMA addr = 0, frame_len = len(msg)
        for i in range(8):
            nic.write8(0x02 + i, 0)  # DMA addr = 0
        nic.write8(0x0A, len(msg) & 0xFF)
        nic.write8(0x0B, 0)
        nic._execute_cmd(0x01)
        self.assertTrue(nic.tx_busy)
        self.assertEqual(sent, [])
        nic.tick(1)
        self.assertEqual(sent[0], msg)

    def test_rx_via_dma(self):
        """RX using DMA with mem_write callback."""
        nic = NetworkDevice()
        ram = bytearray(256)
        nic._mem_write = lambda addr, val: ram.__setitem__(addr % len(ram), val & 0xFF)
        frame = b'incoming'
        nic.inject_frame(frame)
        # Set DMA addr = 0x10
        nic.write8(0x02, 0x10)
        for i in range(1, 8):
            nic.write8(0x02 + i, 0)
        nic._execute_cmd(0x02)  # RECV
        self.assertEqual(nic.frame_len, len(frame))
        self.assertEqual(bytes(ram[0x10:0x10 + len(frame)]), frame)

    def test_reset_clears_state(self):
        nic = NetworkDevice()
        nic.inject_frame(b'test')
        nic._execute_cmd(0x04)  # RESET
        self.assertEqual(len(nic.rx_queue), 0)
        self.assertEqual(nic.tx_count, 0)
        self.assertEqual(nic.rx_count, 0)
        self.assertEqual(nic.frame_len, 0)

    def test_counters(self):
        nic = NetworkDevice()
        sent = []
        nic.on_tx_frame = lambda f: sent.append(f)
        for i in range(3):
            nic.inject_frame(bytes([i]))
        self.assertEqual(nic.rx_count, 3)
        # Send two frames through DMA.
        current = [0]
        nic._mem_read = lambda _addr: current[0]
        for i in range(2):
            current[0] = 0x41 + i
            nic.frame_len = 1
            nic._execute_cmd(0x01)
            nic.tick(1)
        self.assertEqual(nic.tx_count, 2)
        # Read counters via register
        self.assertEqual(nic.read8(0x14), 2)  # TX_COUNT_LO
        self.assertEqual(nic.read8(0x16), 3)  # RX_COUNT_LO

    def test_sysinfo_bank0_size(self):
        """SysInfo register at offset 0x08 reports bank0 size in bytes."""
        si = SystemInfo(bank0_size=1 << 20)  # 1 MiB
        # Read 64-bit value at offset 0x08 (little-endian bytes)
        val = 0
        for i in range(8):
            val |= si.read8(0x08 + i) << (8 * i)
        self.assertEqual(val, 1 << 20)

    def test_sysinfo_hbw_info(self):
        """SysInfo reports HBW base, size, and total memory."""
        si = SystemInfo(bank0_size=1 << 20, hbw_base=0xFFD0_0000,
                        hbw_size=3 * (1 << 20), int_mem_total=4 * (1 << 20))
        # Read HBW base at offset 0x20
        hbw_base = 0
        for i in range(8):
            hbw_base |= si.read8(0x20 + i) << (8 * i)
        self.assertEqual(hbw_base, 0xFFD0_0000)
        # Read HBW size at offset 0x28
        hbw_size = 0
        for i in range(8):
            hbw_size |= si.read8(0x28 + i) << (8 * i)
        self.assertEqual(hbw_size, 3 * (1 << 20))
        # Read total at offset 0x30
        total = 0
        for i in range(8):
            total |= si.read8(0x30 + i) << (8 * i)
        self.assertEqual(total, 4 * (1 << 20))

    def test_sysinfo_cluster_en_rw(self):
        """SysInfo cluster_en at offset 0x18 is read-write."""
        si = SystemInfo()
        self.assertEqual(si.read8(0x18), 0xFF)  # default all enabled
        si.write8(0x18, 0x05)  # enable clusters 0 and 2
        self.assertEqual(si.read8(0x18), 0x05)
        si.write8(0x19, 0x03)  # set byte 1
        self.assertEqual(si.cluster_en, 0xFFFF_FFFF_FFFF_0305)

    def test_bus_routes_nic(self):
        bus = DeviceBus()
        nic = NetworkDevice()
        bus.register(nic)
        # Read STATUS via bus at NIC_BASE offset
        status = bus.read8(NIC_BASE + 0x01)
        self.assertTrue(status & 0x80)  # present

        sent = []
        nic._mem_read = lambda _addr: 0x5A
        nic.on_tx_frame = sent.append
        nic.frame_len = 1
        bus.write8(NIC_BASE, 0x01)
        self.assertTrue(bus.read8(NIC_BASE + 0x01) & 0x01)
        self.assertEqual(sent, [])
        bus.tick(1)
        self.assertFalse(bus.read8(NIC_BASE + 0x01) & 0x01)
        self.assertEqual(sent, [b'Z'])

    def test_tx_latches_descriptor_and_rejects_duplicate_send(self):
        """Live descriptor rewrites cannot replace an owned transaction."""
        nic = NetworkDevice()
        ram = bytearray(64)
        ram[4:7] = b'old'
        ram[16:20] = b'next'
        nic._mem_read = lambda addr: ram[addr]
        sent = []
        nic.on_tx_frame = sent.append
        nic.dma_addr = 4
        nic.frame_len = 3

        nic._execute_cmd(0x01)
        nic.dma_addr = 16
        nic.frame_len = 4
        nic._execute_cmd(0x01)

        self.assertTrue(nic.tx_busy)
        self.assertTrue(nic.error)
        self.assertEqual(sent, [])
        nic.tick(1)
        self.assertEqual(sent, [b'old'])
        self.assertEqual(nic.tx_count, 1)
        self.assertEqual(nic.dma_addr, 16)
        self.assertEqual(nic.frame_len, 4)

    def test_reset_cancels_pending_tx_and_preserves_configuration(self):
        """RESET revokes TX ownership without publishing a late completion."""
        nic = NetworkDevice()
        sent = []
        nic.on_tx_frame = sent.append
        nic._mem_read = lambda _addr: 0xA5
        nic.dma_addr = 0x1234
        nic.frame_len = 1
        nic.irq_ctrl = 0x02
        nic._execute_cmd(0x01)
        self.assertTrue(nic.tx_busy)

        nic._execute_cmd(0x04)
        nic.tick(100)

        self.assertFalse(nic.tx_busy)
        self.assertEqual(sent, [])
        self.assertEqual(nic.tx_count, 0)
        self.assertEqual(nic.irq_status, 0)
        self.assertEqual(nic.dma_addr, 0x1234)
        self.assertEqual(nic.irq_ctrl, 0x02)
        self.assertEqual(nic.frame_len, 0)

    def test_tx_callback_failure_releases_busy_and_reports_completion(self):
        """A broken host observer cannot strand completed guest ownership."""
        nic = NetworkDevice()
        nic._mem_read = lambda _addr: 0xA5
        nic.frame_len = 1

        def fail_callback(_frame):
            raise RuntimeError("host observer failed")

        nic.on_tx_frame = fail_callback
        nic._execute_cmd(0x01)
        nic.tick(1)

        self.assertFalse(nic.tx_busy)
        self.assertTrue(nic.error)
        self.assertEqual(nic.tx_count, 1)
        self.assertEqual(list(nic.tx_queue), [b'\xA5'])
        self.assertEqual(nic.irq_status & 0x02, 0x02)

    def test_frame_limit_rejects_without_truncation(self):
        nic = NetworkDevice()
        big_frame = bytes(2000)
        self.assertFalse(nic.inject_frame(big_frame))
        self.assertEqual(len(nic.rx_queue), 0)
        self.assertTrue(nic.error)

    def test_empty_rx_is_rejected_and_error_is_sticky_until_reset(self):
        nic = NetworkDevice()
        self.assertFalse(nic.inject_frame(b''))
        self.assertEqual(len(nic.rx_queue), 0)
        self.assertTrue(nic.read8(0x01) & 0x08)

        # Neither a status command nor a subsequent valid receive may hide
        # the earlier boundary violation.
        nic._execute_cmd(0x03)
        self.assertTrue(nic.read8(0x01) & 0x08)
        self.assertTrue(nic.inject_frame(b'valid'))
        nic._execute_cmd(0x02)
        self.assertTrue(nic.read8(0x01) & 0x08)

        nic._execute_cmd(0x04)
        self.assertFalse(nic.read8(0x01) & 0x08)

        nic.frame_len = 0
        nic._execute_cmd(0x01)
        self.assertTrue(nic.read8(0x01) & 0x08)
        nic._mem_read = lambda _addr: ord('x')
        nic.frame_len = 1
        nic._execute_cmd(0x01)
        nic.tick(1)
        self.assertTrue(nic.read8(0x01) & 0x08)
        nic._execute_cmd(0x04)
        self.assertFalse(nic.read8(0x01) & 0x08)

    def test_native_nic_matches_empty_rx_and_sticky_error_contract(self):
        sys = make_system()
        cs = sys.cores[0]._cs
        self.assertFalse(cs.nic_inject_frame(b''))
        self.assertEqual(cs.nic_rx_queue_size(), 0)
        self.assertTrue(cs.nic_read8(NIC_BASE + 0x01) & 0x08)

        cs.nic_write8(NIC_BASE + 0x00, 0x03)
        self.assertTrue(cs.nic_read8(NIC_BASE + 0x01) & 0x08)
        self.assertTrue(cs.nic_inject_frame(b'valid'))
        cs.nic_write8(NIC_BASE + 0x00, 0x02)
        self.assertTrue(cs.nic_read8(NIC_BASE + 0x01) & 0x08)

        cs.nic_write8(NIC_BASE + 0x00, 0x04)
        self.assertFalse(cs.nic_read8(NIC_BASE + 0x01) & 0x08)

        cs.nic_write8(NIC_BASE + 0x0A, 0)
        cs.nic_write8(NIC_BASE + 0x0B, 0)
        cs.nic_write8(NIC_BASE + 0x00, 0x01)
        self.assertTrue(cs.nic_read8(NIC_BASE + 0x01) & 0x08)
        cs.nic_write8(NIC_BASE + 0x0A, 1)
        cs.nic_write8(NIC_BASE + 0x00, 0x01)
        self.assertTrue(cs.nic_read8(NIC_BASE + 0x01) & 0x08)
        cs.nic_write8(NIC_BASE + 0x00, 0x04)
        self.assertFalse(cs.nic_read8(NIC_BASE + 0x01) & 0x08)

    def test_irq_events_latch_while_masked_then_assert_when_enabled(self):
        nic = NetworkDevice()
        self.assertEqual(nic.irq_ctrl, 0)
        self.assertFalse(nic.irq_pending)

        self.assertTrue(nic.inject_frame(b'rx'))
        self.assertEqual(nic.read8(0x0D) & 0x01, 0x01)
        self.assertFalse(nic.irq_pending)
        nic.write8(0x0C, 0x01)
        self.assertTrue(nic.irq_pending)
        nic.write8(0x0D, 0x01)
        self.assertFalse(nic.irq_pending)

        nic._mem_read = lambda _addr: 0xA5
        nic.frame_len = 1
        nic.write8(0x0C, 0x00)
        nic._execute_cmd(0x01)
        self.assertEqual(nic.read8(0x0D) & 0x02, 0)
        nic.tick(1)
        self.assertEqual(nic.read8(0x0D) & 0x02, 0x02)
        self.assertFalse(nic.irq_pending)
        nic.write8(0x0C, 0x02)
        self.assertTrue(nic.irq_pending)

    def test_native_irq_and_data_window_match_rtl_contract(self):
        sys = make_system()
        cs = sys.cores[0]._cs

        cs.nic_write8(NIC_BASE + 0x20, 0xDE)
        cs.nic_write8(NIC_BASE + 0x21, 0xAD)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x20), 0xDE)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x20), 0xDE)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x21), 0xAD)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x22), 0)

        cs.nic_write8(NIC_BASE + 0x0C, 0)
        self.assertTrue(cs.nic_inject_frame(b'rx'))
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x0D) & 0x01, 0x01)
        self.assertFalse(cs.nic_irq_pending())
        cs.nic_write8(NIC_BASE + 0x0C, 0x01)
        self.assertTrue(cs.nic_irq_pending())
        cs.nic_write8(NIC_BASE + 0x0D, 0x01)
        self.assertFalse(cs.nic_irq_pending())

        cs.nic_write8(NIC_BASE + 0x0C, 0)
        cs.nic_write8(NIC_BASE + 0x0A, 1)
        cs.nic_write8(NIC_BASE + 0x0B, 0)
        cs.nic_write8(NIC_BASE + 0x00, 0x01)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x0D) & 0x02, 0x02)
        self.assertFalse(cs.nic_irq_pending())
        cs.nic_write8(NIC_BASE + 0x0C, 0x02)
        self.assertTrue(cs.nic_irq_pending())

        cs.nic_write8(NIC_BASE + 0x00, 0x04)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x20), 0)
        self.assertEqual(cs.nic_read8(NIC_BASE + 0x21), 0)

    def test_standard_maximum_ethernet_frame_is_preserved(self):
        nic = NetworkDevice()
        frame = bytes((i & 0xFF) for i in range(1514))
        self.assertTrue(nic.inject_frame(frame))
        self.assertEqual(nic.rx_queue[0], frame)


# ---------------------------------------------------------------------------
#  System / MMIO tests
# ---------------------------------------------------------------------------

class TestSystemMMIO(unittest.TestCase):
    def test_uart_tx_via_cpu(self):
        """CPU writing to UART MMIO address should trigger TX."""
        sys = make_system()
        buf = capture_uart(sys)
        # Full MMIO address = MMIO_BASE + UART_BASE + 0
        uart_addr = MMIO_BASE + UART_BASE
        code = assemble(f"""
            ldi64 r1, {uart_addr}
            ldi r2, 0x41
            st.b r1, r2
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(buf, [0x41])

    def test_sysinfo_read_via_cpu(self):
        """CPU reading SysInfo board ID through MMIO."""
        sys = make_system(ram_kib=64)
        sysinfo_addr = MMIO_BASE + SYSINFO_BASE
        # Read bytes 4 and 5 of the board-id register (contain '4' and '6')
        code = assemble(f"""
            ldi64 r1, {sysinfo_addr + 4}
            ld.b r4, r1
            inc r1
            ld.b r5, r1
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(sys.cpu.regs[4], ord("4"))
        self.assertEqual(sys.cpu.regs[5], ord("6"))

    def test_normal_ram_unaffected(self):
        """Non-MMIO addresses should read/write RAM normally."""
        sys = make_system()
        code = assemble("""
            ldi r1, 0xAA
            ldi64 r4, 0x8000
            st.b r4, r1
            ldi r5, 0
            ld.b r5, r4
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(sys.cpu.regs[5], 0xAA)


# ---------------------------------------------------------------------------
#  HBW memory tests
# ---------------------------------------------------------------------------

class TestHBWMemory(unittest.TestCase):
    """Tests for the High-Bandwidth (HBW) math RAM banks."""

    def test_hbw_direct_read_write(self):
        """CPU can read/write HBW memory at 0xFFD0_0000."""
        sys = make_system()
        hbw_addr = 0xFFD0_0000
        code = assemble(f"""
            ldi r1, 0x42
            ldi64 r4, {hbw_addr}
            st.b r4, r1
            ldi r5, 0
            ld.b r5, r4
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(sys.cpu.regs[5], 0x42)

    def test_hbw_does_not_alias_bank0(self):
        """HBW writes must not corrupt bank 0 RAM."""
        sys = make_system()
        # 0xFFD0_0000 % 0x100000 = 0xD0000 — same offset in bank 0
        bank0_offset = 0xD0000
        hbw_addr = 0xFFD0_0000
        # Write different values to the same offset in bank 0 vs HBW
        sys.cpu.mem_write8(bank0_offset, 0xAA)
        sys.cpu.mem_write8(hbw_addr, 0xBB)
        # Read back — they must be independent
        self.assertEqual(sys.cpu.mem_read8(bank0_offset), 0xAA,
                         "bank 0 should be 0xAA")
        self.assertEqual(sys.cpu.mem_read8(hbw_addr), 0xBB,
                         "HBW should be 0xBB")

    def test_hbw_64bit_access(self):
        """64-bit read/write to HBW memory via CPU mem functions."""
        sys = make_system()
        hbw_addr = 0xFFE0_0000  # bank 2
        val = 0xDEADBEEF_CAFEBABE
        # Use the CPU's (patched) memory functions directly
        sys.cpu.mem_write64(hbw_addr, val)
        result = sys.cpu.mem_read64(hbw_addr)
        self.assertEqual(result, val)

    def test_hbw_bank3(self):
        """Write/read to bank 3 (0xFFF0_0000)."""
        sys = make_system()
        hbw_addr = 0xFFF0_0000
        code = assemble(f"""
            ldi r1, 0x77
            ldi64 r4, {hbw_addr}
            st.b r4, r1
            ldi r5, 0
            ld.b r5, r4
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(sys.cpu.regs[5], 0x77)

    def test_load_binary_to_hbw(self):
        """load_binary() can target HBW addresses."""
        sys = make_system()
        hbw_addr = 0xFFD0_0100
        sys.load_binary(hbw_addr, b'\xAA\xBB\xCC\xDD')
        # Read back via internal HBW buffer
        self.assertEqual(sys._hbw_mem[0x100], 0xAA)
        self.assertEqual(sys._hbw_mem[0x101], 0xBB)
        self.assertEqual(sys._hbw_mem[0x102], 0xCC)
        self.assertEqual(sys._hbw_mem[0x103], 0xDD)

    def test_dma_read_hbw(self):
        """DMA _raw_mem_read routes HBW addresses correctly."""
        sys = make_system()
        sys._hbw_mem[0] = 0x42
        self.assertEqual(sys._raw_mem_read(0xFFD0_0000), 0x42)

    def test_dma_write_hbw(self):
        """DMA _raw_mem_write routes HBW addresses correctly."""
        sys = make_system()
        sys._raw_mem_write(0xFFD0_0000, 0x99)
        self.assertEqual(sys._hbw_mem[0], 0x99)

    def test_hbw_system_has_correct_sizes(self):
        """MegapadSystem creates correct HBW allocation."""
        sys = make_system()
        self.assertEqual(len(sys._hbw_mem), 3 * (1 << 20))
        self.assertEqual(sys.hbw_size, 3 * (1 << 20))

    def test_sysinfo_reports_hbw(self):
        """SysInfo registers reflect HBW configuration."""
        sys = make_system()
        si = sys.sysinfo
        # Read bank0_size at offset 0x08
        val = 0
        for i in range(8):
            val |= si.read8(0x08 + i) << (8 * i)
        self.assertEqual(val, 1024 * 1024)  # 1 MiB
        # Read HBW base at offset 0x20
        val = 0
        for i in range(8):
            val |= si.read8(0x20 + i) << (8 * i)
        self.assertEqual(val, 0xFFD0_0000)
        # Read int_mem_total at offset 0x30
        val = 0
        for i in range(8):
            val |= si.read8(0x30 + i) << (8 * i)
        self.assertEqual(val, 4 * 1024 * 1024)  # 4 MiB


# ---------------------------------------------------------------------------
#  External memory tests
# ---------------------------------------------------------------------------

class TestExternalMemory(unittest.TestCase):
    """Tests for external memory (HyperRAM/SDRAM) emulation."""

    def test_ext_mem_allocation(self):
        """External memory is allocated when ext_mem_size > 0."""
        sys = make_system(ext_mem_mib=4)
        self.assertEqual(len(sys._ext_mem), 4 * (1 << 20))
        self.assertEqual(sys.ext_mem_size, 4 * (1 << 20))
        self.assertEqual(sys.ext_mem_base, 0x0010_0000)
        self.assertEqual(sys.ext_mem_end, 0x0010_0000 + 4 * (1 << 20))

    def test_ext_mem_zero_default(self):
        """No external memory by default."""
        sys = make_system()
        self.assertEqual(len(sys._ext_mem), 0)
        self.assertEqual(sys.ext_mem_size, 0)

    def test_ext_mem_cpu_read_write(self):
        """CPU can read/write external memory at 0x0010_0000."""
        sys = make_system(ext_mem_mib=1)
        ext_addr = 0x0010_0000
        code = assemble(f"""
            ldi r1, 0x55
            ldi64 r4, {ext_addr}
            st.b r4, r1
            ldi r5, 0
            ld.b r5, r4
            halt
        """)
        sys.load_binary(0, code)
        sys.boot()
        run_until(sys)
        self.assertTrue(sys.cpu.halted)
        self.assertEqual(sys.cpu.regs[5], 0x55)

    def test_ext_mem_does_not_alias_bank0(self):
        """External memory writes must not corrupt bank 0 RAM."""
        sys = make_system(ext_mem_mib=1)
        ext_addr = 0x0010_0000
        bank0_addr = 0x0000_0100
        sys.cpu.mem_write8(bank0_addr, 0xAA)
        sys.cpu.mem_write8(ext_addr, 0xBB)
        self.assertEqual(sys.cpu.mem_read8(bank0_addr), 0xAA)
        self.assertEqual(sys.cpu.mem_read8(ext_addr), 0xBB)

    def test_ext_mem_64bit_access(self):
        """64-bit read/write to external memory."""
        sys = make_system(ext_mem_mib=1)
        ext_addr = 0x0010_0100
        val = 0x1234_5678_9ABC_DEF0
        sys.cpu.mem_write64(ext_addr, val)
        result = sys.cpu.mem_read64(ext_addr)
        self.assertEqual(result, val)

    def test_load_binary_to_ext_mem(self):
        """load_binary() can target external memory addresses."""
        sys = make_system(ext_mem_mib=1)
        ext_addr = 0x0010_0200
        sys.load_binary(ext_addr, b'\x11\x22\x33\x44')
        self.assertEqual(sys._ext_mem[0x200], 0x11)
        self.assertEqual(sys._ext_mem[0x201], 0x22)
        self.assertEqual(sys._ext_mem[0x202], 0x33)
        self.assertEqual(sys._ext_mem[0x203], 0x44)

    def test_dma_read_ext_mem(self):
        """DMA _raw_mem_read routes ext mem addresses correctly."""
        sys = make_system(ext_mem_mib=1)
        sys._ext_mem[0] = 0x42
        self.assertEqual(sys._raw_mem_read(0x0010_0000), 0x42)

    def test_dma_write_ext_mem(self):
        """DMA _raw_mem_write routes ext mem addresses correctly."""
        sys = make_system(ext_mem_mib=1)
        sys._raw_mem_write(0x0010_0000, 0x99)
        self.assertEqual(sys._ext_mem[0], 0x99)

    def test_sysinfo_reports_ext_mem(self):
        """SysInfo registers reflect external memory configuration."""
        sys = make_system(ext_mem_mib=4)
        si = sys.sysinfo
        # Read ext_mem_base at offset 0x38
        val = 0
        for i in range(8):
            val |= si.read8(0x38 + i) << (8 * i)
        self.assertEqual(val, 0x0010_0000)
        # Read ext_mem_size at offset 0x40
        val = 0
        for i in range(8):
            val |= si.read8(0x40 + i) << (8 * i)
        self.assertEqual(val, 4 * (1 << 20))

    def test_sysinfo_zero_ext_mem(self):
        """SysInfo reports zero for ext mem when not configured."""
        sys = make_system()
        si = sys.sysinfo
        val = 0
        for i in range(8):
            val |= si.read8(0x38 + i) << (8 * i)
        self.assertEqual(val, 0)
        val = 0
        for i in range(8):
            val |= si.read8(0x40 + i) << (8 * i)
        self.assertEqual(val, 0)


# ---------------------------------------------------------------------------
#  Framebuffer device tests
# ---------------------------------------------------------------------------

class TestFramebuffer(unittest.TestCase):
    """Tests for the FramebufferDevice MMIO peripheral."""

    def test_default_state(self):
        """Framebuffer powers on with sensible defaults."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        self.assertEqual(fb.width, 320)
        self.assertEqual(fb.height, 240)
        self.assertEqual(fb.stride, 320)
        self.assertEqual(fb.mode, 0)
        self.assertEqual(fb.enable, 0)
        self.assertEqual(fb.vsync_count, 0)
        self.assertEqual(fb.fb_base, 0)
        # Status: disabled, no vblank
        self.assertEqual(fb.read8(0x48), 0)

    def test_width_height_readback(self):
        """Write and read back width/height as 32-bit LE."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        # Write width = 640 (0x0280) LE across 4 bytes at offset 0x08
        fb.write8(0x08, 0x80)
        fb.write8(0x09, 0x02)
        fb.write8(0x0A, 0x00)
        fb.write8(0x0B, 0x00)
        self.assertEqual(fb.width, 640)
        # Read back
        self.assertEqual(fb.read8(0x08), 0x80)
        self.assertEqual(fb.read8(0x09), 0x02)
        # Write height = 480 (0x01E0)
        fb.write8(0x10, 0xE0)
        fb.write8(0x11, 0x01)
        fb.write8(0x12, 0x00)
        fb.write8(0x13, 0x00)
        self.assertEqual(fb.height, 480)
        self.assertEqual(fb.read8(0x10), 0xE0)
        self.assertEqual(fb.read8(0x11), 0x01)

    def test_stride_readback(self):
        """Write and read back stride as 32-bit LE."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        # stride = 1024 (0x0400)
        fb.write8(0x18, 0x00)
        fb.write8(0x19, 0x04)
        fb.write8(0x1A, 0x00)
        fb.write8(0x1B, 0x00)
        self.assertEqual(fb.stride, 1024)
        self.assertEqual(fb.read8(0x18), 0x00)
        self.assertEqual(fb.read8(0x19), 0x04)

    def test_fb_base_64bit(self):
        """Write and read back fb_base as 64-bit LE."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        # Set base to 0xFFD0_0000 (HBW Bank 1 start)
        addr = 0xFFD0_0000
        for i in range(8):
            fb.write8(i, (addr >> (8 * i)) & 0xFF)
        self.assertEqual(fb.fb_base, addr)
        for i in range(8):
            self.assertEqual(fb.read8(i), (addr >> (8 * i)) & 0xFF)

    def test_mode_register(self):
        """Mode register accepts 0–3, masks higher bits."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.write8(0x20, 2)
        self.assertEqual(fb.mode, 2)
        self.assertEqual(fb.read8(0x20), 2)
        # Write 0xFF → should mask to 3
        fb.write8(0x20, 0xFF)
        self.assertEqual(fb.mode, 3)

    def test_enable_disable(self):
        """Enable/disable scanout and check status."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        self.assertEqual(fb.read8(0x48), 0)  # disabled
        # Enable scanout (bit 0)
        fb.write8(0x28, 0x01)
        self.assertEqual(fb.enable, 1)
        self.assertEqual(fb.read8(0x28), 1)
        # Status should show enabled
        self.assertTrue(fb.read8(0x48) & 1)
        # Disable
        fb.write8(0x28, 0x00)
        self.assertEqual(fb.enable, 0)
        self.assertFalse(fb.read8(0x48) & 1)

    def test_vsync_counter(self):
        """Vsync counter increments on tick when enabled."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.write8(0x28, 0x01)  # enable
        fb.cycles_per_frame = 100  # fast for testing
        # Not yet enough cycles
        fb.tick(50)
        self.assertEqual(fb.vsync_count, 0)
        self.assertFalse(fb.vblank)
        # Pass the threshold
        fb.tick(50)
        self.assertEqual(fb.vsync_count, 1)
        self.assertTrue(fb.vblank)
        # Read vsync counter
        self.assertEqual(fb.read8(0x30), 1)
        self.assertEqual(fb.read8(0x31), 0)

    def test_vsync_disabled_no_tick(self):
        """Vsync counter does NOT tick when disabled."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.cycles_per_frame = 10
        fb.tick(100)
        self.assertEqual(fb.vsync_count, 0)

    def test_vsync_ack(self):
        """Writing 1 to FB_VSYNC clears vblank flag."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.write8(0x28, 0x01)  # enable
        fb.cycles_per_frame = 10
        fb.tick(10)
        self.assertTrue(fb.vblank)
        # Ack: write 1 as 32-bit LE
        fb.write8(0x30, 0x01)
        fb.write8(0x31, 0x00)
        fb.write8(0x32, 0x00)
        fb.write8(0x33, 0x00)
        self.assertFalse(fb.vblank)
        # Status should no longer show vblank
        self.assertFalse(fb.read8(0x48) & 2)

    def test_palette_write(self):
        """Write palette entries via idx+data sequence."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        # Set palette index 0
        fb.write8(0x38, 0)
        # Write RGB 0x00FF8040 → actually 0x00FF8040 & 0x00FFFFFF = 0xFF8040
        fb.write8(0x40, 0x40)  # B
        fb.write8(0x41, 0x80)  # G
        fb.write8(0x42, 0xFF)  # R
        fb.write8(0x43, 0x00)  # high byte (masked)
        self.assertEqual(fb.palette[0], 0xFF8040)

    def test_palette_auto_increment(self):
        """Palette index auto-increments after each data write."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.write8(0x38, 5)  # start at index 5
        # Write two entries
        for color, idx in [(0x112233, 5), (0x445566, 6)]:
            fb.write8(0x40, color & 0xFF)
            fb.write8(0x41, (color >> 8) & 0xFF)
            fb.write8(0x42, (color >> 16) & 0xFF)
            fb.write8(0x43, 0x00)
        self.assertEqual(fb.palette[5], 0x112233)
        self.assertEqual(fb.palette[6], 0x445566)
        # Index should now be 7
        self.assertEqual(fb.pal_idx, 7)

    def test_palette_wraps(self):
        """Palette index wraps from 255 to 0."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.write8(0x38, 255)
        # Write one entry at index 255
        fb.write8(0x40, 0xAA)
        fb.write8(0x41, 0xBB)
        fb.write8(0x42, 0xCC)
        fb.write8(0x43, 0x00)
        self.assertEqual(fb.palette[255], 0xCCBBAA)
        # Should wrap to 0
        self.assertEqual(fb.pal_idx, 0)

    def test_irq_pending(self):
        """IRQ pending only when both vsync IRQ enabled and vblank set."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        fb.cycles_per_frame = 10
        # Enable scanout only (no IRQ)
        fb.write8(0x28, 0x01)
        fb.tick(10)
        self.assertTrue(fb.vblank)
        self.assertFalse(fb.irq_pending)  # IRQ not enabled
        # Enable IRQ (bit 1)
        fb.write8(0x28, 0x03)
        self.assertTrue(fb.irq_pending)
        # Ack clears it
        fb.write8(0x30, 0x01)
        fb.write8(0x31, 0x00)
        fb.write8(0x32, 0x00)
        fb.write8(0x33, 0x00)
        self.assertFalse(fb.irq_pending)

    def test_frame_bytes(self):
        """frame_bytes property reflects stride × height."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        self.assertEqual(fb.frame_bytes, 320 * 240)
        # Change stride
        fb.write8(0x18, 0x00)
        fb.write8(0x19, 0x04)
        fb.write8(0x1A, 0x00)
        fb.write8(0x1B, 0x00)  # stride = 1024
        self.assertEqual(fb.frame_bytes, 1024 * 240)

    def test_bpp_per_mode(self):
        """bpp() returns correct bytes per pixel for each mode."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        for mode, expected_bpp in [(0, 1), (1, 2), (2, 2), (3, 4)]:
            fb.write8(0x20, mode)
            self.assertEqual(fb.bpp(), expected_bpp,
                             f"mode {mode} should be {expected_bpp} bpp")

    def test_bus_routing(self):
        """FramebufferDevice is reachable through the DeviceBus."""
        from devices import FramebufferDevice, DeviceBus, FB_BASE
        bus = DeviceBus()
        fb = FramebufferDevice()
        bus.register(fb)
        # Write mode = 2 via bus
        bus.write8(FB_BASE + 0x20, 2)
        self.assertEqual(fb.mode, 2)
        # Read back via bus
        self.assertEqual(bus.read8(FB_BASE + 0x20), 2)

    def test_system_wired(self):
        """FramebufferDevice is accessible through MegapadSystem."""
        sys = make_system()
        self.assertIsNotNone(sys.fb)
        self.assertEqual(sys.fb.width, 320)
        self.assertEqual(sys.fb.height, 240)
        # Check bus routing
        from devices import FB_BASE
        sys.bus.write8(FB_BASE + 0x20, 1)
        self.assertEqual(sys.fb.mode, 1)

    def test_default_palette_grayscale(self):
        """Default palette is a grayscale ramp."""
        from devices import FramebufferDevice
        fb = FramebufferDevice()
        self.assertEqual(fb.palette[0], 0x000000)
        self.assertEqual(fb.palette[128], 0x808080)
        self.assertEqual(fb.palette[255], 0xFFFFFF)


# ---------------------------------------------------------------------------
#  BIOS tests
# ---------------------------------------------------------------------------

class TestBIOS(unittest.TestCase):

    # Class-level cache: snapshot of system state after BIOS boots to idle.
    # Avoids re-assembling and re-booting for each of the 128+ tests.
    _bios_snapshot = None   # (mem_bytes, cpu_state)
    _bios_code_cache = None

    @classmethod
    def _save_cpu_state(cls, cpu):
        """Capture all CPU register/flag state for snapshot."""
        return {
            'pc': cpu.pc,
            'regs': list(cpu.regs),
            'psel': cpu.psel, 'xsel': cpu.xsel, 'spsel': cpu.spsel,
            'flag_z': cpu.flag_z, 'flag_c': cpu.flag_c,
            'flag_n': cpu.flag_n, 'flag_v': cpu.flag_v,
            'flag_p': cpu.flag_p, 'flag_g': cpu.flag_g,
            'flag_i': cpu.flag_i, 'flag_s': cpu.flag_s,
            'd_reg': cpu.d_reg, 'q_out': cpu.q_out, 't_reg': cpu.t_reg,
            'ivt_base': cpu.ivt_base, 'ivec_id': cpu.ivec_id,
            'trap_addr': cpu.trap_addr,
            'halted': cpu.halted, 'idle': cpu.idle,
            'cycle_count': cpu.cycle_count,
            '_ext_modifier': cpu._ext_modifier,
        }

    @classmethod
    def _restore_cpu_state(cls, cpu, state):
        """Restore CPU register/flag state from snapshot."""
        cpu.pc = state['pc']
        cpu.regs[:] = state['regs']
        for k in ('psel', 'xsel', 'spsel',
                   'flag_z', 'flag_c', 'flag_n', 'flag_v',
                   'flag_p', 'flag_g', 'flag_i', 'flag_s',
                   'd_reg', 'q_out', 't_reg',
                   'ivt_base', 'ivec_id', 'trap_addr',
                   'halted', 'idle', 'cycle_count', '_ext_modifier'):
            setattr(cpu, k, state[k])

    @classmethod
    def _ensure_bios_snapshot(cls):
        """Build the BIOS-booted snapshot once (class-level)."""
        if cls._bios_snapshot is not None:
            return
        cls._bios_labels = {}
        with open(BIOS_PATH) as f:
            cls._bios_code_cache = assemble(f.read(),
                                            labels_out=cls._bios_labels)

        sys_obj = make_system(ram_kib=256)
        sys_obj.load_binary(0, cls._bios_code_cache)
        cls._register_accel_hooks(sys_obj)
        sys_obj.boot()
        # Run until BIOS reaches idle (waiting for UART input)
        for _ in range(2_000_000):
            if sys_obj.cpu.halted or sys_obj.cpu.idle:
                break
            try:
                sys_obj.step()
            except HaltError:
                break
        else:
            raise AssertionError(
                "BIOS snapshot boot exhausted its infrastructure step "
                "budget before reaching idle"
            )
        cls._bios_snapshot = (
            bytes(sys_obj.cpu.mem),
            cls._save_cpu_state(sys_obj.cpu),
        )

    def setUp(self):
        self.__class__._ensure_bios_snapshot()
        self.bios_code = self.__class__._bios_code_cache

    @classmethod
    def _register_accel_hooks(cls, sys_obj):
        """Register C++ accelerator hooks for BIOS graphics words."""
        labels = getattr(cls, '_bios_labels', {})
        if labels and hasattr(sys_obj.cpu, 'register_accel_hook'):
            for name, hook_id, code_size in [
                ('w_rect_fill', 1, 53),
                ('w_blit_glyph', 2, 79),
                ('w_vram_copy', 3, 131),
                ('w_blit_string', 4, 175),
            ]:
                if name in labels:
                    sys_obj.cpu.register_accel_hook(
                        labels[name],
                        hook_id,
                        code_size,
                    )

    def _boot_bios(self, ram_kib=256, storage_image=None, ext_mem_mib=0):
        # Fast path: restore from snapshot (default 256K, no storage)
        if (ram_kib == 256 and storage_image is None
                and ext_mem_mib == 0
                and self.__class__._bios_snapshot is not None):
            return self._boot_bios_fast()
        # Slow path: fresh boot (non-default RAM size or storage)
        sys = make_system(ram_kib=ram_kib, storage_image=storage_image,
                          ext_mem_mib=ext_mem_mib)
        buf = capture_uart(sys)
        sys.load_binary(0, self.bios_code)
        self._register_accel_hooks(sys)
        sys.boot()
        return sys, buf

    def _boot_bios_fast(self):
        """Restore BIOS from snapshot — instant boot."""
        mem_bytes, cpu_state = self.__class__._bios_snapshot
        sys = make_system(ram_kib=256)
        buf = capture_uart(sys)
        sys.cpu.mem[:len(mem_bytes)] = mem_bytes
        self._restore_cpu_state(sys.cpu, cpu_state)
        self._register_accel_hooks(sys)
        # Restore TX ring buffer base from R19 (set during BIOS boot)
        r19 = sys.cpu.regs[19]
        if r19 and r19 < len(mem_bytes):
            sys.uart._tx_ring_base = r19
        return sys, buf

    def _run_forth(self, sys, buf, input_lines: list[str],
                   max_steps=2_000_000) -> str:
        """Feed newline-terminated Forth commands and collect UART output.

        Injects input in 256-byte chunks and uses run_batch() for CPU
        execution.  Always appends BYE to ensure the CPU halts.
        """
        payload = "\n".join(input_lines) + "\nBYE\n"
        data = payload.encode()
        pos = 0
        total = 0

        while total < max_steps:
            if sys.cpu.halted:
                break
            if sys.cpu.idle and not sys.uart.has_rx_data:
                if pos < len(data):
                    chunk = _next_line_chunk(data, pos)
                    sys.uart.inject_input(chunk)
                    pos += len(chunk)
                else:
                    break
                continue
            batch = sys.run_batch(min(100_000, max_steps - total))
            total += max(batch, 1)

        return uart_text(buf)

    # -- Banner --

    def test_boot_banner(self):
        # Force slow path — we need to see the banner printed during boot
        sys = make_system(ram_kib=256)
        buf = capture_uart(sys)
        sys.load_binary(0, self.bios_code)
        sys.boot()
        text = self._run_forth(sys, buf, [])
        self.assertIn("Megapad-64 Forth BIOS v1.0", text)
        self.assertIn("RAM:", text)
        self.assertIn("ok", text)

    # -- Basic number printing --

    def test_print_zero(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0 ."])
        self.assertIn("0 ", text)

    def test_print_positive(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["42 ."])
        self.assertIn("42 ", text)

    def test_print_negative(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["-7 ."])
        self.assertIn("-7 ", text)

    def test_hex_literal(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0xFF ."])
        self.assertIn("255 ", text)

    # -- Arithmetic --

    def test_add(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["3 4 + ."])
        self.assertIn("7 ", text)

    def test_subtract(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["10 3 - ."])
        self.assertIn("7 ", text)

    def test_multiply(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["6 7 * ."])
        self.assertIn("42 ", text)

    def test_um_star_unsigned_widening_boundaries(self):
        """UM* returns exact low/high halves at unsigned carry edges."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "HEX",
            '0 -1 UM* ." ZH=" U. ." ZL=" U.',
            '-1 -1 UM* ." MH=" U. ." ML=" U.',
            '0x8000000000000000 2 UM* ." CH=" U. ." CL=" U.',
        ])
        self.assertIn("ZH=0 ", text)
        self.assertIn("ZL=0 ", text)
        self.assertIn("MH=FFFFFFFFFFFFFFFE ", text)
        self.assertIn("ML=1 ", text)
        self.assertIn("CH=1 ", text)
        self.assertIn("CL=0 ", text)

    def test_divmod(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["100 7 /MOD . ."])
        self.assertIn("14 2 ", text)

    # -- Stack operations --

    def test_dup(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["5 DUP . ."])
        self.assertIn("5 5 ", text)

    def test_swap(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["1 2 SWAP . ."])
        self.assertIn("1 2 ", text)

    def test_drop(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["1 2 DROP ."])
        self.assertIn("1 ", text)

    def test_dot_s(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["1 2 3 .S", "DROP DROP DROP"])
        self.assertIn("<3>", text)
        self.assertIn("1", text)

    def test_depth(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["42 DEPTH ."])
        self.assertIn("1 ", text)

    # -- Comparison & logic --

    def test_less_than(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["3 5 < ."])
        self.assertIn("-1 ", text)

    def test_greater_than(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["5 3 > ."])
        self.assertIn("-1 ", text)

    def test_equal(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["7 7 = ."])
        self.assertIn("-1 ", text)

    def test_and(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0xFF 0x0F AND ."])
        self.assertIn("15 ", text)

    def test_or(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0xF0 0x0F OR ."])
        self.assertIn("255 ", text)

    # -- Memory --

    def test_store_fetch(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["42 0x2000 !", "0x2000 @ ."])
        self.assertIn("42 ", text)

    def test_c_store_c_fetch(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0xAB 0x3000 C!", "0x3000 C@ ."])
        self.assertIn("171 ", text)

    def test_on(self):
        """ON stores TRUE (-1) at addr."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0 0x2000 !",          # pre-clear
            "0x2000 ON",           # store TRUE
            "0x2000 @ .",          # should print -1
        ])
        self.assertIn("-1 ", text)

    def test_2store_2fetch(self):
        """2! stores and 2@ fetches a cell pair."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "111 222 0x2000 2!",   # store: 222 at 0x2000, 111 at 0x2008
            "0x2000 2@ . .",       # fetch: x2=222 printed first, x1=111 second
        ])
        self.assertIn("222 ", text)
        self.assertIn("111 ", text)

    def test_2store_2fetch_roundtrip(self):
        """2! followed by 2@ preserves exact values."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0xDEAD 0xBEEF 0x2000 2!",
            "0x2000 2@ . .",
        ])
        self.assertIn("48879 ", text)   # 0xBEEF = 48879
        self.assertIn("57005 ", text)   # 0xDEAD = 57005

    def test_fill_dump(self):
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["0x2000 16 0xCC FILL", "0x2000 16 DUMP"])
        self.assertIn("CC", text)

    def test_wfill(self):
        """WFILL writes 16-bit words; verify via W@ reads."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0x3000 8 0xBEEF WFILL",        # fill 8 halfwords at 0x3000
            "0x3000 W@ .",                    # first word
            "0x300E W@ .",                    # last word (0x3000 + 7*2)
        ])
        self.assertIn("48879 ", text)         # 0xBEEF = 48879

    def test_wfill_zero_count(self):
        """WFILL with n=0 is a no-op — must not crash."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0x3000 0 0x1234 WFILL",
            "42 .",                           # prove interpreter still alive
        ])
        self.assertIn("42 ", text)

    def test_rect_fill(self):
        """RECT-FILL writes a w×h block of 16-bit pixels."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            # Fill 4×3 rectangle at 0x10000, stride=8 bytes (4 pixels * 2)
            # Use addresses above BIOS ROM (~0x8100) to avoid corruption.
            "0x10000 8 4 3 0xF800 RECT-FILL",  # red RGB565
            # Check first pixel of each row
            "0x10000 W@ .",                    # row 0
            "0x10008 W@ .",                    # row 1 (0x10000 + stride 8)
            "0x10010 W@ .",                    # row 2 (0x10000 + stride 16)
        ])
        # 0xF800 = 63488
        self.assertIn("63488 ", text)

    def test_rect_fill_zero_dims(self):
        """RECT-FILL with w=0 or h=0 is a no-op."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0x10000 16 0 5 0xFFFF RECT-FILL",  # w=0
            "0x10000 16 5 0 0xFFFF RECT-FILL",  # h=0
            "99 .",
        ])
        self.assertIn("99 ", text)

    def test_blit_glyph(self):
        """BLIT-GLYPH renders foreground pixels from a font bitmap."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            # Store an 8-byte glyph pattern at 0x10000
            # (addresses above BIOS ROM ~0x8100 to avoid corruption)
            # Row 0: 0xFF (all 8 bits set)
            # Rows 1-7: 0x00
            "0xFF 0x10000 C!",
            "0x00 0x10001 C!  0x00 0x10002 C!  0x00 0x10003 C!",
            "0x00 0x10004 C!  0x00 0x10005 C!  0x00 0x10006 C!  0x00 0x10007 C!",
            # Blit to pixel address 0x20000, stride=16, fg=0x07E0 (green)
            "0x10000 0x20000 16 0x07E0 BLIT-GLYPH",
            # Row 0 should have green pixels (all 8 set)
            "0x20000 W@ .",                    # first pixel of row 0
            "0x2000E W@ .",                    # last pixel of row 0 (col 7)
            # Row 1 should be untouched (transparent)
            "0x20010 W@ .",                    # first pixel of row 1
        ])
        # 0x07E0 = 2016 (green)
        self.assertIn("2016 ", text)
        # Row 1 should be 0 (untouched memory)
        self.assertIn("0 ", text)

    def test_blit_glyph_null(self):
        """BLIT-GLYPH with glyph-addr=0 is a no-op."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0 0x20000 16 0xFFFF BLIT-GLYPH",
            "77 .",
        ])
        self.assertIn("77 ", text)

    def test_vram_copy(self):
        """VRAM-COPY copies a w×h rectangle from src to dst."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            # Write a known pattern: 2 bytes wide, 2 rows, stride=4
            "0xAA 0x10000 C!  0xBB 0x10001 C!",  # row 0
            "0xCC 0x10004 C!  0xDD 0x10005 C!",  # row 1 (stride=4)
            # Copy to 0x20000
            "0x10000 0x20000 4 2 2 VRAM-COPY",
            # Read back
            "0x20000 C@ .",  # should be 0xAA = 170
            "0x20001 C@ .",  # should be 0xBB = 187
            "0x20004 C@ .",  # should be 0xCC = 204
            "0x20005 C@ .",  # should be 0xDD = 221
        ])
        self.assertIn("170 ", text)
        self.assertIn("187 ", text)
        self.assertIn("204 ", text)
        self.assertIn("221 ", text)

    def test_vram_copy_zero(self):
        """VRAM-COPY with w=0 or h=0 is a no-op."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0x10000 0x20000 16 0 5 VRAM-COPY",  # w=0
            "0x10000 0x20000 16 5 0 VRAM-COPY",  # h=0
            "42 .",
        ])
        self.assertIn("42 ", text)

    def test_vram_copy_overlap(self):
        """VRAM-COPY handles overlapping dst > src (scroll-up pattern)."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            # Fill 3 rows: row0=0x11, row1=0x22, row2=0x33, stride=4, w=2
            "0x11 0x10000 C!  0x11 0x10001 C!",
            "0x22 0x10004 C!  0x22 0x10005 C!",
            "0x33 0x10008 C!  0x33 0x10009 C!",
            # Copy row1+row2 (src=0x10004) over row0+row1 (dst=0x10000)
            # This is dst < src → forward copy, should work fine
            "0x10004 0x10000 4 2 2 VRAM-COPY",
            "0x10000 C@ .",  # was 0x11, now should be 0x22 = 34
            "0x10004 C@ .",  # was 0x22, now should be 0x33 = 51
        ])
        self.assertIn("34 ", text)
        self.assertIn("51 ", text)

    def test_blit_string(self):
        """BLIT-STRING renders multiple chars at ascending pixel offsets."""
        sys, buf = self._boot_bios()
        # Font base at 0x30000.  Char offset = (c - 0x20) * 8.
        # 'A' = 0x41 → offset 0x108, 'B' = 0x42 → offset 0x110
        # Place 0xFF in row 0 of each glyph so pixels appear.
        text = self._run_forth(sys, buf, [
            # Store 2-char string "AB" at 0x10000
            "65 0x10000 C!  66 0x10001 C!",
            # Write glyph data for 'A' at 0x30108 and 'B' at 0x30110
            "0xFF 0x30108 C!",   # 'A' row 0 – all bits set
            "0xFF 0x30110 C!",   # 'B' row 0 – all bits set
            # BLIT-STRING ( c-addr len pixel-addr stride fg16 font-base -- )
            "0x10000 2 0x20000 64 0x07E0 0x30000 BLIT-STRING",
            # Char 'A' glyph row 0 should have green pixels at 0x20000
            # Char 'B' starts at 0x20000 + 16 = 0x20010
            "0x20000 W@ .",
            "0x20010 W@ .",
        ])
        # Both glyphs should have produced foreground pixels (0x07E0 = 2016)
        self.assertIn("2016", text, f"Char A glyph missing pixels: {text}")
        # Count occurrences – both chars should produce the same fg colour
        self.assertEqual(text.count("2016"), 2,
                         f"Expected 2 pixel outputs, got: {text}")

    def test_blit_string_zero_len(self):
        """BLIT-STRING with len=0 is a no-op."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "0x10000 0 0x20000 64 0xFFFF 0x30000 BLIT-STRING",
            "88 .",
        ])
        self.assertIn("88 ", text)

