            text = self._run_forth(sys, buf, [
                "1 2 + .",
                "9999 1+ ULAND @ + .",
                "MODULE? networking.f 19999 1+ + .",
                "29999 1+ U-INIT-DONE @ + .",
                "39999 1+ U-DICT-BASE @ + .",
                "49999 1+ U-DICT-HERE @ + .",
            ], max_steps=600_000_000)
            self.assertIn("Insufficient ext mem for userland dictionary", text)
            self.assertIn("3 ", text)
