    def test_standard_autoexec_does_not_reenter_bios_fsload(self):
        """Userland networking uses KDOS REQUIRE while KDOS autoboot is live."""
        fs = build_sample_image()
        autoexec = fs.read_file("autoexec.f")
        marker = b"\n_ENTER-UL\n"
        self.assertEqual(autoexec.count(marker), 1)
        autoexec = autoexec.replace(
            marker,
            marker + b': FSLOAD ABORT" nested BIOS FSLOAD" ;\n',
            1,
        )
        fs.delete_file("autoexec.f")
        fs.inject_file("autoexec.f", autoexec, ftype=FTYPE_FORTH)
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            fs.save(path)
        try:
            sys, buf = self._boot_bios(
                ram_kib=1024,
                storage_image=path,
                ext_mem_mib=128,
            )
            text = self._run_forth(
                sys,
                buf,
                [
                    "MODULE? networking.f .",
                    "' PORT-INIT DROP .\" NETWORK-TAIL\"",
                ],
                max_steps=900_000_000,
            )
            self.assertNotIn("nested BIOS FSLOAD", text)
            self.assertNotIn("? (not found)", text)
            self.assertIn("-1 ", text)
            self.assertIn("NETWORK-TAIL", text)
        finally:
            os.unlink(path)

    # -- Phase 7 edge cases: MMIO byte-serialization helpers --

    def test_disk_read_sector_zero_addr(self):
        """disk_read_sectors works with DMA addr at bottom of RAM."""
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            sys, buf = self._boot_bios(storage_image=path)
            # Write a known pattern to sector 0, then read to a low addr
            text = self._run_forth(sys, buf, [
                "VARIABLE dbuf  512 ALLOT",
                "0x42 dbuf C!",
                "0 DISK-SEC!  dbuf DISK-DMA!  1 DISK-N!  DISK-WRITE",
                "0 dbuf C!",    # clear
                "DISK-READ",    # re-read
                "dbuf C@ .",
            ])
            self.assertIn("66 ", text)  # 0x42 = 66
        finally:
            if os.path.exists(path):
                os.unlink(path)

    def test_disk_read_high_sector_number(self):
        """disk_read_sectors serialises sector numbers > 255 correctly."""
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            sys, buf = self._boot_bios(storage_image=path)
            # Write to sector 300 (> 255, exercises byte-2 of sector num)
            text = self._run_forth(sys, buf, [
                "VARIABLE dbuf  512 ALLOT",
                "0xAB dbuf C!",
                "300 DISK-SEC!  dbuf DISK-DMA!  1 DISK-N!  DISK-WRITE",
                "0 dbuf C!",
                "DISK-READ",
                "dbuf C@ .",
            ])
            self.assertIn("171 ", text)  # 0xAB = 171
        finally:
            if os.path.exists(path):
                os.unlink(path)

    def test_disk_multibatch_preserves_regs(self):
        """Multi-batch disk reads (>255 sectors) don't corrupt R8/UART."""
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            sys, buf = self._boot_bios(ram_kib=1024, storage_image=path)
            # Read 300 sectors = 2 batches (255 + 45).
            # After the read, EMIT (via R8/UART) must still work.
            text = self._run_forth(sys, buf, [
                "VARIABLE dbuf  153600 ALLOT",   # 300*512
                "0 DISK-SEC!  dbuf DISK-DMA!  300 DISK-N!  DISK-READ",
                ".\" ok-after-multi\"",
            ])
            self.assertIn("ok-after-multi", text)
        finally:
            if os.path.exists(path):
                os.unlink(path)

    def test_disk_status_after_disk_read(self):
        """DISK@ still works after a disk read (R8 not clobbered)."""
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
        try:
            os.unlink(path)
            sys, buf = self._boot_bios(storage_image=path)
            text = self._run_forth(sys, buf, [
                "VARIABLE dbuf  512 ALLOT",
                "0 DISK-SEC!  dbuf DISK-DMA!  1 DISK-N!  DISK-READ",
                "DISK@ 0x80 AND .",
            ])
            self.assertIn("128 ", text)  # bit7 = present
        finally:
            if os.path.exists(path):
                os.unlink(path)

    # -- Phase 8: Cooperative multitasking (PAUSE/TASK-YIELD/BACKGROUND) --

    def test_task_status_no_task(self):
        """TASK? returns 0 when no background task is running."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["1 TASK? ."])
        self.assertIn("0 ", text)

    def test_pause_noop_without_task(self):
        """PAUSE is a silent no-op when no background task exists."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "PAUSE",
            ".\" ok-pause\"",
        ])
        self.assertIn("ok-pause", text)

    def test_background_oneshot(self):
        """BACKGROUND runs a one-shot word that returns, then TASK? → 0."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE result",
            ": BG-WORK  42 result ! ;",
            "' BG-WORK BACKGROUND",
            "1 TASK? .",
            "PAUSE",
            "1 TASK? .",
            "result @ .",
        ])
        # Before PAUSE: task is queued (TASK? → 1)
        # After PAUSE: task ran and returned (cleanup sentinel fires),
        # TASK? → 0, result = 42
        self.assertIn("1 ", text)   # TASK? before PAUSE
        self.assertIn("0 ", text)   # TASK? after PAUSE
        self.assertIn("42 ", text)  # result from BG-WORK

    def test_background_task_yield_roundtrip(self):
        """TASK-YIELD in background task correctly suspends and resumes."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE bg-counter",
            ": BG-LOOP  0 bg-counter !  5 0 DO  bg-counter @ 1 + bg-counter !  TASK-YIELD  LOOP ;",
            "' BG-LOOP BACKGROUND",
            "6 0 DO PAUSE LOOP",
            "bg-counter @ .",
        ])
        # BG-LOOP increments counter 5 times, TASK-YIELDing after each.
        # 6 PAUSEs ensure all 5 iterations complete + 1 extra (nop after task exits).
        self.assertIn("5 ", text)

    def test_task_id_tracks_executing_coroutine(self):
        """TASK-ID distinguishes foreground from the active background slot."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE seen-task-id",
            ": RECORD-TASK-ID  TASK-ID seen-task-id !  TASK-YIELD ;",
            "TASK-ID .",
            "' RECORD-TASK-ID BACKGROUND2",
            "PAUSE",
            "TASK-ID .",
            "seen-task-id @ .",
            "PAUSE",
        ])
        nums = [int(w) for w in text.split() if w.isdigit()]
        self.assertEqual(nums[-3:], [0, 0, 2],
                         f"TASK-ID should report foreground/background contexts: {text!r}")

    def test_task_stop_cancels_task(self):
        """TASK-STOP prevents further execution of background task."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE bg-count",
            ": BG-INF  BEGIN  bg-count @ 1 + bg-count !  TASK-YIELD  AGAIN ;",
            "' BG-INF BACKGROUND",
            "PAUSE",
            "PAUSE",
            "1 TASK-STOP",
            "1 TASK? .",
            "bg-count @ .",
        ])
        # After 2 PAUSEs, counter = 2. TASK-STOP kills it.
        self.assertIn("0 ", text)   # TASK? after TASK-STOP
        self.assertIn("2 ", text)   # bg-count

    def test_pause_preserves_data_stack(self):
        """PAUSE does not corrupt the foreground data stack."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": BG-NOP  TASK-YIELD ;",
            "' BG-NOP BACKGROUND",
            "111 222 333",
            "PAUSE",
            ". . .",
        ])
        # Stack should be: 333 222 111 (printed in LIFO order by .)
        self.assertIn("333 ", text)
        self.assertIn("222 ", text)
        self.assertIn("111 ", text)

    def test_background_replaces_existing(self):
        """Starting a new BACKGROUND replaces any running task."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE r1  VARIABLE r2",
            ": BG1  BEGIN  r1 @ 1 + r1 !  TASK-YIELD  AGAIN ;",
            ": BG2  BEGIN  r2 @ 1 + r2 !  TASK-YIELD  AGAIN ;",
            "' BG1 BACKGROUND",
            "PAUSE PAUSE",
            "' BG2 BACKGROUND",
            "PAUSE PAUSE",
            "1 TASK-STOP",
            "r1 @ .",
            "r2 @ .",
        ])
        # BG1 runs for 2 PAUSEs → r1=2.  Then BG2 replaces it for 2 more → r2=2.
        self.assertIn("2 ", text)

    def test_background2_slot(self):
        """BACKGROUND2 runs a task in slot 2 independently of slot 1."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE s2-val",
            ": BG2-WORK  99 s2-val ! ;",
            "' BG2-WORK BACKGROUND2",
            "2 TASK? .",
            "PAUSE",
            "2 TASK? .",
            "s2-val @ .",
        ])
        self.assertIn("1 ", text)   # active before PAUSE
        self.assertIn("0 ", text)   # done after PAUSE
        self.assertIn("99 ", text)

    def test_background3_slot(self):
        """BACKGROUND3 runs a task in slot 3."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE s3-val",
            ": BG3-WORK  77 s3-val ! ;",
            "' BG3-WORK BACKGROUND3",
            "3 TASK? .",
            "PAUSE",
            "3 TASK? .",
            "s3-val @ .",
        ])
        self.assertIn("1 ", text)
        self.assertIn("0 ", text)
        self.assertIn("77 ", text)

    def test_multi_slot_round_robin(self):
        """PAUSE round-robins through active slots 1, 2, 3."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE c1  VARIABLE c2  VARIABLE c3",
            ": T1  BEGIN  c1 @ 1 + c1 !  TASK-YIELD  AGAIN ;",
            ": T2  BEGIN  c2 @ 1 + c2 !  TASK-YIELD  AGAIN ;",
            ": T3  BEGIN  c3 @ 1 + c3 !  TASK-YIELD  AGAIN ;",
            "' T1 BACKGROUND",
            "' T2 BACKGROUND2",
            "' T3 BACKGROUND3",
            # 9 PAUSEs: round-robin across 3 tasks → each runs 3 times
            "9 0 DO PAUSE LOOP",
            "1 TASK-STOP  2 TASK-STOP  3 TASK-STOP",
            "c1 @ .",
            "c2 @ .",
            "c3 @ .",
        ])
        self.assertIn("3 ", text)   # each counter = 3

    def test_task_count(self):
        """#TASKS returns number of active background tasks."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "#TASKS .",
            ": NOOP-BG  TASK-YIELD ;",
            "' NOOP-BG BACKGROUND",
            "#TASKS .",
            "' NOOP-BG BACKGROUND2",
            "#TASKS .",
            "1 TASK-STOP  2 TASK-STOP",
            "#TASKS .",
        ])
        # #TASKS outputs: 0, 1, 2, 0
        # (echoed "1 TASK-STOP 2 TASK-STOP" inserts extra digits)
        nums = [int(w) for w in text.split() if w.isdigit()]
        self.assertEqual(nums[0], 0, f"First #TASKS should be 0, got {nums}")
        self.assertEqual(nums[1], 1, f"Second #TASKS should be 1, got {nums}")
        self.assertEqual(nums[2], 2, f"Third #TASKS should be 2, got {nums}")
        self.assertEqual(nums[-1], 0, f"Final #TASKS should be 0, got {nums}")

    def test_slots_independent_stop(self):
        """Stopping one slot doesn't affect others."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE a  VARIABLE b",
            ": TA  BEGIN  a @ 1 + a !  TASK-YIELD  AGAIN ;",
            ": TB  BEGIN  b @ 1 + b !  TASK-YIELD  AGAIN ;",
            "' TA BACKGROUND",
            "' TB BACKGROUND2",
            "PAUSE PAUSE",
            "1 TASK-STOP",
            "PAUSE PAUSE",
            "2 TASK-STOP",
            "a @ .",
            "b @ .",
        ])
        # Round-robin: 2 PAUSEs across 2 slots → each runs 1 time.
        # After stopping slot 1: 2 PAUSEs with 1 slot → slot 2 runs 2 more.
        # Total: a=1, b=3
        nums = [int(w) for w in text.split() if w.isdigit()]
        self.assertEqual(nums[-2], 1, f"a should be 1, got {nums}")   # a
        self.assertEqual(nums[-1], 3, f"b should be 3, got {nums}")   # b

    # -- Phase 9: SEP diagnostic words --

    def test_sep_psel_fetch(self):
        """SEP-PSEL@ returns 3 (main code always runs with PSEL=R3)."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["SEP-PSEL@ ."])
        self.assertIn("3 ", text)

    def test_sep_xsel_fetch(self):
        """SEP-XSEL@ returns the current XSEL."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["SEP-XSEL@ ."])
        # XSEL is typically set during boot; just check it returns a number
        self.assertRegex(text, r"\d+\s+ok")

    def test_sep_t_fetch(self):
        """SEP-T@ reads the T register (0 if MARK was never called)."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["SEP-T@ ."])
        self.assertIn("0 ", text)

    def test_sep_snap_updates_t(self):
        """SEP-SNAP snapshots XSEL||PSEL into T, then SEP-T@ reads it."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, ["SEP-SNAP SEP-T@ ."])
        # After SEP-SNAP: T = XSEL||PSEL.  PSEL=3, XSEL varies.
        # T low nibble should be 3.
        self.assertRegex(text, r"\d+\s+ok")
        # Extract the printed number — low nibble must be 3
        import re
        m = re.search(r"(\d+)\s+ok", text)
        self.assertIsNotNone(m)
        t_val = int(m.group(1))
        self.assertEqual(t_val & 0xF, 3, f"T low nibble should be PSEL=3, got {t_val:#x}")

    # -- Timer words --

    def test_timer_store(self):
        """TIMER! sets the compare-match register."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "1000 TIMER!",
        ])
        # Verify compare register was set
        self.assertEqual(sys.timer.compare, 1000)

    def test_timer_ctrl_store(self):
        """TIMER-CTRL! sets the timer control register."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "7 TIMER-CTRL!",
        ])
        # enable + IRQ + auto-reload = 7
        self.assertEqual(sys.timer.control, 7)

    def test_ms_fetch_reconstructs_all_eight_uptime_bytes(self):
        """MS@ must not wrap when the third uptime byte becomes nonzero."""
        sys, buf = self._boot_bios()
        expected = 0x0102030405060708
        sys.rtc.ctrl = 0
        sys.rtc.uptime_ms = expected
        text = self._run_forth(sys, buf, ["MS@ ."])
        self.assertIn(f"{expected} ", text)

    def test_epoch_fetch_reconstructs_all_eight_epoch_bytes(self):
        """EPOCH@ must preserve every byte used by token expiration."""
        sys, buf = self._boot_bios()
        expected = 0x0102030405060708
        sys.rtc.ctrl = 0
        sys.rtc.epoch_ms = expected
        text = self._run_forth(sys, buf, ["EPOCH@ ."])
        self.assertIn(f"{expected} ", text)

    def test_ei_di(self):
        """EI! and DI! toggle the global interrupt flag.

        Note: the BIOS REPL returns via RET.L which always re-enables
        interrupts (flag_i=1).  We therefore cannot observe DI! surviving
        the return to the REPL.  Instead we test that EI! enables
        interrupts and that DI! compiles/runs without error.
        """
        sys, buf = self._boot_bios()
        # Initially interrupts are disabled
        self.assertEqual(sys.cpu.flag_i, 0)
        text = self._run_forth(sys, buf, ["EI!"])
        self.assertEqual(sys.cpu.flag_i, 1)
        # DI! executes without error (flag_i restored to 1 by RET.L)
        text = self._run_forth(sys, buf, ["DI!"])
        self.assertNotIn("???", text)

    # ------------------------------------------------------------------
    #  BIOS v0.5 — new words
    # ------------------------------------------------------------------

    def test_exit_early_return(self):
        """EXIT returns from a colon definition early."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TE 1 IF 42 EXIT THEN 77 ;",
            "TE .",
        ])
        self.assertIn("42 ", text)
        # 77 must not appear as execution output (only in echoed definition)
        after_run = text.split("TE .")[-1] if "TE ."  in text else text
        self.assertNotIn("77", after_run)

    def test_to_r_r_from(self):
        """>R and R> move values via the return stack."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TR 10 >R 20 R> + . ;",
            "TR",
        ])
        self.assertIn("30 ", text)

    def test_r_fetch(self):
        """R@ peeks the return stack without popping."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TRF 7 >R R@ R> + . ;",
            "TRF",
        ])
        self.assertIn("14 ", text)

    def test_j_nested_loop(self):
        """J accesses the outer loop index from a nested loop."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TJ 3 0 DO 2 0 DO J . LOOP LOOP ;",
            "TJ",
        ])
        # Outer loop: 0,1,2 — each printed twice (inner loop runs 2x)
        nums = [x for x in text.split() if x.isdigit()]
        self.assertEqual(nums[-6:], ["0", "0", "1", "1", "2", "2"])

    def test_nested_qdo_zero_trip_preserves_outer_loop(self):
        """An inner zero-trip ?DO must not consume the outer loop frame."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TNQ 0 9 0 ?DO I 0 ?DO 1+ LOOP LOOP ;",
            "TNQ . 12345 .",
        ])
        nums = [x for x in text.split() if x.isdigit()]
        self.assertEqual(nums[-2:], ["36", "12345"])

    def test_nested_loop_keeps_eight_fixups_per_scope(self):
        """Outer ?DO fixups must not reduce an inner loop's eight slots."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TNQ8 2 0 ?DO 10 0 DO",
            " I 0 = IF LEAVE THEN I 1 = IF LEAVE THEN",
            " I 2 = IF LEAVE THEN I 3 = IF LEAVE THEN",
            " I 4 = IF LEAVE THEN I 5 = IF LEAVE THEN",
            " I 6 = IF LEAVE THEN I 7 = IF LEAVE THEN",
            " LOOP LOOP 77 ;",
            "TNQ8 .",
        ])
        self.assertNotIn("Too many LEAVEs", text)
        nums = [x for x in text.split() if x.isdigit()]
        self.assertEqual(nums[-1], "77")

    def test_unloop_exit(self):
        """UNLOOP + EXIT breaks out of a loop cleanly."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TU 10 0 DO I DUP 5 = IF . UNLOOP EXIT THEN DROP LOOP 77 . ;",
            "TU",
        ])
        self.assertIn("5 ", text)
        # 77 must not appear in execution output (only in echoed definition)
        after_run = text.split("TU\r\n")[-1] if "TU\r\n" in text else text.split("TU")[-1]
        self.assertNotIn("77", after_run)

    def test_plus_loop(self):
        """+LOOP increments by a custom step."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TPL 20 0 DO I . 5 +LOOP ;",
            "TPL",
        ])
        nums = [x for x in text.split() if x.isdigit()]
        self.assertEqual(nums[-4:], ["0", "5", "10", "15"])

    def test_again_loop(self):
        """BEGIN...AGAIN creates an infinite loop (exit via UNLOOP/EXIT or test)."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "VARIABLE CNT 0 CNT !",
            ": TAG BEGIN CNT @ 1+ DUP CNT ! 5 = IF EXIT THEN AGAIN ;",
            "TAG CNT @ .",
        ])
        self.assertIn("5 ", text)

    def test_state_bracket(self):
        """STATE, [, and ] control compile/interpret mode."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TSB [ 3 4 + ] LITERAL . ;",
            "TSB",
        ])
        self.assertIn("7 ", text)

    def test_literal(self):
        """LITERAL compiles a computed value."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TL [ 100 ] LITERAL . ;",
            "TL",
        ])
        self.assertIn("100 ", text)

    def test_immediate_word(self):
        """IMMEDIATE marks a user word as execute-during-compilation."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TEN 10 ; IMMEDIATE",
            ": TI [ TEN ] LITERAL . ;",
            "TI",
        ])
        self.assertIn("10 ", text)

    def test_create(self):
        """CREATE makes a word that pushes its data-field address."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "CREATE MYDAT 42 ,",
            "MYDAT @ .",
        ])
        self.assertIn("42 ", text)

    def test_squote(self):
        """S\" pushes string address and length."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ': TS S" HELLO" TYPE ;',
            "TS",
        ])
        self.assertIn("HELLO", text)

    def test_zero_gt(self):
        """0> returns true for positive, false for zero/negative."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": T0G 0> . ;",
            "5 T0G",
            "0 T0G",
            "-3 T0G",
        ])
        # Extract just the results after each T0G call
        results = []
        for part in text.split("T0G"):
            for tok in part.split():
                if tok.lstrip('-').isdigit():
                    results.append(tok)
                    break
        # 5 0> = -1 (true), 0 0> = 0, -3 0> = 0
        self.assertEqual(results[-3:], ["-1", "0", "0"])

    def test_not_equal(self):
        """<> returns true when values differ."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TNE <> . ;",
            "3 4 TNE",
            "5 5 TNE",
        ])
        results = []
        for part in text.split("TNE"):
            for tok in part.split():
                if tok.lstrip('-').isdigit():
                    results.append(tok)
                    break
        self.assertEqual(results[-2:], ["-1", "0"])

    def test_zero_ne(self):
        """0<> returns true for nonzero."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            ": TZN 0<> . ;",
            "7 TZN",
            "0 TZN",
        ])
        results = []
        for part in text.split("TZN"):
            for tok in part.split():
                if tok.lstrip('-').isdigit():
                    results.append(tok)
                    break
        self.assertEqual(results[-2:], ["-1", "0"])

    def test_qdup(self):
        """?DUP duplicates only nonzero values."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "3 ?DUP DEPTH .",
            "DROP DROP",
            "0 ?DUP DEPTH .",
        ])
        # After 3 ?DUP: stack has 3 3 → depth 2
        # After 0 ?DUP: stack has 0 → depth 1
        nums = [x for x in text.split() if x.isdigit()]
        self.assertIn("2", nums)
        self.assertIn("1", nums)

    def test_min_max_bios(self):
        """MIN and MAX work at the BIOS level."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "3 7 MIN .",
            "3 7 MAX .",
        ])
        nums = [x for x in text.split() if x.isdigit()]
        self.assertIn("3", nums)
        self.assertIn("7", nums)

    def test_cells_cell_plus(self):
        """CELLS and CELL+ work at the BIOS level."""
        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "5 CELLS .",
            "100 CELL+ .",
        ])
        nums = [x for x in text.split() if x.isdigit()]
        self.assertIn("40", nums)
        self.assertIn("108", nums)

