        sys, buf = self._boot_bios()
        text = self._run_forth(sys, buf, [
            "1 2 3 -ROT .S",
        ])
        # After -ROT: stack is 3 1 2 (TOS=2)
        self.assertIn("3", text)
        self.assertIn("1", text)
        self.assertIn("2", text)

