    # -- Sample kernels --

    def test_kfill_kernel(self):
        """kfill fills a buffer with a byte."""
        text = self._run_kdos([
            "0 1 64 BUFFER kfb",
            "42 kfb kfill",
            "kfb B.DATA C@ .",
        ])
        idx = text.rfind("HELP")
        out = text[idx:] if idx >= 0 else text
        self.assertIn("42 ", out)

    def test_kadd_kernel(self):
        """kadd adds two buffers."""
        text = self._run_kdos([
            "0 1 64 BUFFER ka1",
            "0 1 64 BUFFER ka2",
            "0 1 64 BUFFER ka3",
            "10 ka1 B.FILL",
            "20 ka2 B.FILL",
            "ka1 ka2 ka3 kadd",
            "ka3 B.DATA C@ .",
        ])
        idx = text.rfind("HELP")
        out = text[idx:] if idx >= 0 else text
        self.assertIn("30 ", out)

    def test_ksum_kernel(self):
        """ksum sums all bytes in a buffer."""
        text = self._run_kdos([
            "0 1 64 BUFFER ksb",
            "1 ksb B.FILL",
            "ksb ksum .",
        ])
        idx = text.rfind("HELP")
        out = text[idx:] if idx >= 0 else text
        self.assertIn("64 ", out)

    def test_kstats_kernel(self):
        """kstats returns sum, min, max."""
        text = self._run_kdos([
            "0 1 64 BUFFER ksb2",
            "5 ksb2 B.FILL",
            "10 ksb2 B.DATA C!",
            "1 ksb2 B.DATA 1+ C!",
            "ksb2 kstats",
            ". . .",
        ])
        # sum=5*62+10+1=321, min=1, max=10
        # . prints max first (TOS), then min, then sum
        self.assertIn("10 ", text)   # max
        self.assertIn("1 ", text)    # min

    def test_kscale_kernel(self):
        """kscale multiplies buffer by scalar."""
        text = self._run_kdos([
            "0 1 64 BUFFER kcb",
            "2 kcb B.FILL",
            "3 kcb kscale",
            "kcb B.DATA C@ .",
        ])
        idx = text.rfind("HELP")
        out = text[idx:] if idx >= 0 else text
        self.assertIn("6 ", out)

    def test_kthresh_kernel(self):
        """kthresh sets bytes < threshold to 0, >= to 255."""
        text = self._run_kdos([
            "0 1 64 BUFFER ktb",
            "50 ktb B.FILL",
            "100 ktb B.DATA C!",
            "75 ktb kthresh",
            "ktb B.DATA C@ .",
            "ktb B.DATA 1+ C@ .",
        ])
        idx = text.rfind("HELP")
        out = text[idx:] if idx >= 0 else text
        self.assertIn("255 ", out)   # 100 >= 75 → 255
        self.assertIn("0 ", out)     # 50 < 75 → 0

