    def test_fs_load(self):
        """FS-LOAD reads MP64FS superblock and prints confirmation."""
        path = self._make_formatted_image()
        try:
            text = self._run_kdos(["FS-LOAD"], storage_image=path)
            self.assertIn("MP64FS loaded", text)
        finally:
            os.unlink(path)

    def test_fs_sync_does_not_publish_after_checked_flush_failure(self):
        """FS-SYNC throws before its caller can report durable success."""
        path = self._make_formatted_image()
        try:
            text = self._run_kdos([
                "FS-LOAD",
                ': SYNC-FAIL-PROBE FS-SYNC ."  SYNC-PUBLISHED" ;',
                "SYNC-FAIL-PROBE",
                '."  STATUS=" DISK-IO-STATUS @ .',
            ], storage_image=path, storage_faults=[{
                "stage": "flush",
                "result": STORAGE_RESULT_FLUSH_FAILURE,
                "command": STORAGE_CMD_FLUSH,
            }])
            self.assertIn("MP64FS loaded", text)
            self.assertEqual(text.count("SYNC-PUBLISHED"), 1)
            self.assertIn("Disk flush failed", text)
            self.assertIn("STATUS=13 ", text)
        finally:
            os.unlink(path)

    def test_format_does_not_publish_after_checked_flush_failure(self):
        """FORMAT sets FS-OK and prints success only after durable flush."""
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            f.write(b"\x00" * (2048 * SECTOR_SIZE))
        try:
            text = self._run_kdos([
                ': FORMAT-FAIL-PROBE FORMAT ."  FORMAT-PUBLISHED" ;',
                "FORMAT-FAIL-PROBE",
                '."  STATUS=" DISK-IO-STATUS @ .',
                '."  FSOK=" FS-OK @ .',
            ], storage_image=path, storage_faults=[{
                "stage": "flush",
                "result": STORAGE_RESULT_FLUSH_FAILURE,
                "command": STORAGE_CMD_FLUSH,
            }])
            self.assertNotIn("MP64FS formatted", text)
            self.assertEqual(text.count("FORMAT-PUBLISHED"), 1)
            self.assertIn("Disk flush failed", text)
            self.assertIn("STATUS=13 ", text)
            self.assertIn("FSOK=0 ", text)
        finally:
            os.unlink(path)

    def test_fs_load_dynamic_geometry(self):
        """KDOS mounts and reports every sector in an 8192-sector image."""
        fs = MP64FS(total_sectors=8192)
        fs.format()
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            fs.save(path)
        try:
            text = self._run_kdos([
                "FS-LOAD",
                "FS-SUPER 4 + W@ . FS-TOTAL @ . FS-BMAP-N @ .",
                "FS-DIR-START . FS-DSTART .",
                "FS-FREE",
            ], storage_image=path)
            self.assertIn("MP64FS loaded", text)
            self.assertIn("1 8192 2 ", text)
            self.assertIn("3 15 ", text)
            self.assertIn("8177  free sectors", text)
        finally:
            os.unlink(path)

    def test_fs_load_rejects_inconsistent_geometry(self):
        """KDOS leaves FS-OK clear when disk geometry is inconsistent."""
        fs = MP64FS(total_sectors=8192)
        fs.format()
        struct.pack_into("<H", fs.img, 14, 4)  # directory must start at 3
        with tempfile.NamedTemporaryFile(suffix=".img", delete=False) as f:
            path = f.name
            fs.save(path)
        try:
            text = self._run_kdos(["FS-LOAD", "FS-OK @ ."], storage_image=path)
            self.assertIn("Invalid MP64FS", text)
            self.assertIn("0 ", text)
        finally:
            os.unlink(path)

