            "server-ctx @ tc-slot @ tc-gen @ server-alpn 8 "
            "TLS-SERVER-CONTEXT-BEGIN",
            '." BEGIN-IOR=" . DUP server-ctx-generation ! '
            '." BEGIN-GEN=" .',
            '." CTX-GEN1=" server-ctx @ TLS-CTX.GENERATION @ .',
            "server-alpn 8 120 FILL",
            '." ROLE=" server-ctx @ TLS-CTX.ROLE @ .',
