            "TLS-SERVER-CONTEXT-BEGIN",
            '." LIVE-IOR=" . ." LIVE-GEN=" .',
            '." REFS-LIVE=" tc-slot @ 1- _TC@ TC.REFS + @ .',
            "tc-slot @ tc-gen @ TLS-CREDENTIAL-DELETE",
