            f"server-ctx @ ch-default {len(hello_default)} "
            "TLS-PARSE-CLIENT-HELLO 2DROP",
            'server-ctx @ _TLS-SERVER-CERTIFICATE-POLICY ." SHA1-DENY=" .',
            '." DENY-FLAGS=" server-ctx @ TLS-RXW.SERVER-META TSM.FLAGS + @ .',
