    # --- 12b: ICMP auto-responder ---

    @staticmethod
    def _build_icmp_echo_req_frame(dst_mac, src_mac, src_ip, dst_ip,
                                    ident=0x1234, seq=1, payload=b''):
        """Build a full Ethernet+IPv4+ICMP echo request frame."""
        # ICMP message
        icmp = bytearray(8 + len(payload))
        icmp[0] = 8   # type=8 echo request
        icmp[1] = 0   # code=0
        icmp[4] = (ident >> 8) & 0xFF
        icmp[5] = ident & 0xFF
        icmp[6] = (seq >> 8) & 0xFF
        icmp[7] = seq & 0xFF
        icmp[8:] = payload
        # ICMP checksum
        s = 0
        padded = bytes(icmp) + (b'\x00' if len(icmp) % 2 else b'')
        for i in range(0, len(padded), 2):
            s += (padded[i] << 8) | padded[i+1]
        while s > 0xFFFF:
            s = (s & 0xFFFF) + (s >> 16)
        cksum = (~s) & 0xFFFF
        icmp[2] = (cksum >> 8) & 0xFF
        icmp[3] = cksum & 0xFF

        # IPv4 header
        ip_hdr = bytearray(20)
        ip_hdr[0] = 0x45
        total_len = 20 + len(icmp)
        ip_hdr[2] = (total_len >> 8) & 0xFF
        ip_hdr[3] = total_len & 0xFF
        ip_hdr[6] = 0x40  # DF
        ip_hdr[8] = 64    # TTL
        ip_hdr[9] = 1     # ICMP
        ip_hdr[12:16] = bytes(src_ip)
        ip_hdr[16:20] = bytes(dst_ip)
        s = 0
        for i in range(0, 20, 2):
            s += (ip_hdr[i] << 8) | ip_hdr[i+1]
        while s > 0xFFFF:
            s = (s & 0xFFFF) + (s >> 16)
        cksum = (~s) & 0xFFFF
        ip_hdr[10] = (cksum >> 8) & 0xFF
        ip_hdr[11] = cksum & 0xFF

        # Ethernet
        eth = bytes(dst_mac) + bytes(src_mac) + b'\x08\x00'
        return eth + bytes(ip_hdr) + bytes(icmp)

    def test_icmp_handle_echo_req(self):
        """ICMP-HANDLE should return -1 for an echo request."""
        nic_mac = [0x02, 0x4D, 0x50, 0x36, 0x34, 0x00]
        frame = self._build_icmp_echo_req_frame(
            nic_mac, [0xAA]*6,
            [10, 0, 0, 1], [192, 168, 1, 100],
            payload=b'hello123')
        text = self._run_kdos([
            "ARP-CLEAR",
            "192 168 1 100 IP-SET",
            # Pre-cache ARP for the sender
            "CREATE sip 4 ALLOT  10 sip C!  0 sip 1+ C!  0 sip 2 + C!  1 sip 3 + C!",
            "CREATE smac 6 ALLOT  smac 6 170 FILL",
            "sip smac ARP-INSERT",
            "IP-RECV ICMP-HANDLE .",
        ], nic_frames=[frame])
        self.assertIn("-1 ", text)

    def test_icmp_odd_checksum_rejects_bad_then_accepts_valid(self):
        """Odd-length ICMP verification includes the final payload byte."""
        good = self._build_icmp_echo_req_frame(
            self.NIC_MAC, self.OTHER_MAC,
            [10, 0, 0, 1], [192, 168, 1, 100], payload=b'XYZ')
        bad = bytearray(good)
        bad[-1] ^= 0x01
        text = self._run_kdos([
            "192 168 1 100 IP-SET",
            'IP-RECV ICMP-RX ."  bad-len=" . DROP',
            'IP-RECV ICMP-RX ."  good-len=" . 0<> ."  good=" .',
        ], nic_frames=[bytes(bad), good])
        self.assertIn("bad-len=0 ", text)
        self.assertIn("good-len=11 ", text)
        self.assertIn("good=-1 ", text)

