        text = self._run_kdos([
            "192 168 1 100 IP-SET",
            "UDP-RECV DROP UDP-H.DATA NIP",
            str(len(dns_data)),
            "DNS-PARSE-RESPONSE .",
        ], nic_frames=[frame])
        self.assertIn("0 ", text)

