    def test_tcp_partial_ack_trims_suffix_across_wrap(self):
        """Repeated cumulative ACKs trim the retained suffix across uint32 wrap."""
        nic_mac = [0x02, 0x4D, 0x50, 0x36, 0x34, 0x00]
