            '0 TCB-N TCB.STATE @ ."  FAILED-STATE=" .',
            '0 TCB-N TCB.TX-LEN @ ."  FAILED-LEN=" .',
            '0 TCB-N TCB.RETRIES @ ."  FAILED-RETRIES=" .',
